int distance(int a, int b) {
    if (a >= b) {
        return a - b;
    }
    return b - a;
}

int distance(int a, int b) {
    int diff = a - b;
    if (diff < 0) {
        diff = -diff;
    }
    return diff;
}

int distance(int a, int b) {
    return a >= b ? a - b : b - a;
}

